 values(auth.uid(),v_actor_code,'products.'||p_action,'product',p_product_id::text,left(nullif(trim(p_note),''),500),jsonb_build_object('product_code',v_row.product_code,'previous_status',v_row.listing_status));
end $function$

CREATE OR REPLACE FUNCTION private.create_product_inquiry(p_product_id uuid, p_message text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_product record;
  v_conversation_id uuid;
  v_title text;
  v_message text := left(btrim(coalesce(p_message, '')), 500);
begin
  if v_user_id is null then
    raise exception 'লগইন করে Buyer হিসেবে Inquiry পাঠান।';
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = v_user_id and p.role = 'buyer' and p.account_status = 'active'
  ) then
    raise exception 'শুধু সক্রিয় Buyer অ্যাকাউন্ট Inquiry পাঠাতে পারবে।';
  end if;

  select p.id, p.seller_id, p.product_code, p.product_name
  into v_product
  from public.products p
  join public.business_profiles b on b.id = p.business_id
  where p.id = p_product_id
    and p.listing_status = 'approved'
    and b.approval_status = 'approved';

  if not found then
    raise exception 'পণ্যটি পাওয়া যায়নি অথবা বর্তমানে অনুমোদিত নয়।';
  end if;

  if v_product.seller_id = v_user_id then
    raise exception 'নিজের পণ্যে Inquiry পাঠানো যাবে না।';
  end if;

  v_title := left(
    'Product Inquiry • ' || v_product.product_code || ' • ' ||
    v_product.product_name ||
    case when v_message <> '' then ' • Buyer note: ' || v_message else '' end,
    900
  );

  insert into public.conversations (conversation_type, created_by, title, status)
  values ('direct', v_user_id, v_title, 'active')
  returning id into v_conversation_id;

  insert into public.conversation_participants
    (conversation_id, user_id, invited_by, invitation_status, joined_at)
  values
    (v_conversation_id, v_user_id, v_user_id, 'accepted', now()),
    (v_conversation_id, v_product.seller_id, v_user_id, 'pending', null);

  return v_conversation_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.manage_marketplace_listing(p_target_type text, p_target_id uuid, p_action text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid:=auth.uid(); v_actor_code text; v_permission text;
  v_old_status text; v_new_status text; v_owner uuid; v_name text;
begin
  if v_actor is null then raise exception 'লগইন প্রয়োজন।' using errcode='42501'; end if;
  if p_target_type not in ('product','business') or p_action not in ('suspend','restore','cancel') then
    raise exception 'Target বা action সঠিক নয়।';
  end if;
  if p_reason is null or length(trim(p_reason))<5 or length(trim(p_reason))>1000 then
    raise exception 'কারণ কমপক্ষে ৫ এবং সর্বোচ্চ ১০০০ অক্ষরের হতে হবে।';
  end if;
  if p_target_type='product' then
    v_permission:=case p_action when 'suspend' then 'products.suspend' when 'restore' then 'products.restore' else 'products.cancel' end;
  else
    if p_action<>'suspend' then raise exception 'Business restore/cancel এখনো অনুমোদিত workflow-তে নেই।'; end if;
    v_permission:='businesses.suspend';
  end if;
  if not private.has_nexora_permission(v_permission) then
    raise exception 'এই কাজের অনুমতি আপনার নেই: %',v_permission using errcode='42501';
  end if;
  select admin_code into v_actor_code from public.admin_staff where user_id=v_actor and is_active=true;
  if v_actor_code is null then raise exception 'সক্রিয় Admin record পাওয়া যায়নি।' using errcode='42501'; end if;

  if p_target_type='product' then
    select listing_status,seller_id,product_name into v_old_status,v_owner,v_name
      from public.products where id=p_target_id for update;
    if not found then raise exception 'পণ্য পাওয়া যায়নি।'; end if;
    if p_action='suspend' and v_old_status not in ('approved','pending') then raise exception 'এই অবস্থায় পণ্য স্থগিত করা যাবে না।'; end if;
    if p_action='restore' and v_old_status<>'suspended' then raise exception 'শুধু স্থগিত পণ্য পুনরায় চালু করা যাবে।'; end if;
    if p_action='cancel' and v_old_status in ('cancelled','rejected') then raise exception 'পণ্যটি ইতিমধ্যে বাতিল/প্রত্যাখ্যাত।'; end if;
    v_new_status:=case p_action when 'suspend' then 'suspended' when 'restore' then 'approved' else 'cancelled' end;
    update public.products set listing_status=v_new_status,admin_note=trim(p_reason),
      reviewed_by=v_actor,reviewed_at=now(),updated_at=now() where id=p_target_id;
  else
    select approval_status,seller_id,display_name into v_old_status,v_owner,v_name
      from public.business_profiles where id=p_target_id for update;
    if not found then raise exception 'Business Profile পাওয়া যায়নি।'; end if;
    if v_old_status not in ('approved','pending') then raise exception 'এই অবস্থায় Business স্থগিত করা যাবে না।'; end if;
    v_new_status:='suspended';
    update public.business_profiles set approval_status=v_new_status,admin_note=trim(p_reason),
      reviewed_by=v_actor,reviewed_at=now(),updated_at=now() where id=p_target_id;
  end if;
  insert into public.admin_audit_logs(actor_user_id,actor_admin_code,action_key,target_type,target_id,reason,details)
  values(v_actor,v_actor_code,'marketplace.'||p_target_type||'.'||p_action,p_target_type,p_target_id::text,
    trim(p_reason),jsonb_build_object('name',v_name,'owner_id',v_owner,'old_status',v_old_status,'new_status',v_new_status,'permission',v_permission));
  return jsonb_build_object('success',true,'target_type',p_target_type,'new_status',v_new_status);
end;
$function$

CREATE OR REPLACE FUNCTION private.manage_nexora_assistant_admin(p_email text, p_action text, p_department_key text DEFAULT NULL::text, p_permissions jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_actor_code text;
  v_target uuid;
  v_staff public.admin_staff%rowtype;
  v_code text;
  v_permission text;
  v_permissions text[] := array[]::text[];
  v_details jsonb;
begin
  if v_actor is null or not private.is_nexora_super_admin() then
    raise exception 'শুধু সক্রিয় Super Admin এই কাজ করতে পারবেন।' using errcode='42501';
  end if;
  if p_action not in ('create','update','deactivate') then raise exception 'অবৈধ action।'; end if;

  select admin_code into v_actor_code from public.admin_staff
  where user_id=v_actor and admin_level='super_admin' and is_active=true;

  select id into v_target from auth.users where lower(email)=lower(trim(p_email)) limit 1;
  if v_target is null then raise exception 'এই ইমেইলে কোনো নিবন্ধিত অ্যাকাউন্ট পাওয়া যায়নি।'; end if;
  if v_target=v_actor then raise exception 'নিজের Super Admin অ্যাকাউন্ট পরিবর্তন করা যাবে না।'; end if;

  if p_action in ('create','update') then
    if p_department_key is null or not exists (
      select 1 from public.admin_departments where department_key=p_department_key and is_assignable=true
    ) then raise exception 'সঠিক বিভাগ নির্বাচন করুন।'; end if;
    if jsonb_typeof(coalesce(p_permissions,'[]'::jsonb)) <> 'array' then raise exception 'অনুমতির তালিকা array হতে হবে।'; end if;
    for v_permission in select jsonb_array_elements_text(coalesce(p_permissions,'[]'::jsonb)) loop
      if not exists (select 1 from public.admin_permission_catalog c
        where c.permission_key=v_permission and c.department_key=p_department_key) then
        raise exception 'এই বিভাগের জন্য অনুমতি বৈধ নয়: %', v_permission;
      end if;
      v_permissions := array_append(v_permissions,v_permission);
    end loop;
  end if;

  select * into v_staff from public.admin_staff where user_id=v_target for update;

  if p_action='create' then
    if found then raise exception 'এই ব্যবহারকারীর Admin record আগে থেকেই আছে। Update ব্যবহার করুন।'; end if;
    if not exists (select 1 from public.profiles where id=v_target and role='buyer' and account_status='active') then
      raise exception 'শুধু সক্রিয় Buyer অ্যাকাউন্টকে Assistant Admin করা যাবে। আগে আলাদা Buyer অ্যাকাউন্ট তৈরি করুন।';
    end if;
    perform pg_advisory_xact_lock(hashtext('nexora-assistant-admin-code'));
    select 'NEX-AA-' || lpad((coalesce(max(substring(admin_code from '[0-9]+$')::bigint),0)+1)::text,4,'0')
      into v_code from public.admin_staff where admin_code like 'NEX-AA-%';
    update public.profiles set role='admin',updated_at=now() where id=v_target;
    insert into public.admin_staff(user_id,admin_code,admin_level,department_key,is_active,created_by)
      values(v_target,v_code,'assistant_admin',p_department_key,true,v_actor);
    insert into public.admin_permission_grants(admin_user_id,permission_key,is_allowed,granted_by)
      select v_target, unnest(v_permissions), true, v_actor;
    v_details := jsonb_build_object('email',lower(trim(p_email)),'admin_code',v_code,
      'department_key',p_department_key,'permissions',to_jsonb(v_permissions));
  elsif p_action='update' then
    if not found or v_staff.admin_level <> 'assistant_admin' then raise exception 'এই ব্যবহারকারী Assistant Admin নন।'; end if;
    update public.admin_staff set department_key=p_department_key,is_active=true,updated_at=now() where user_id=v_target;
    delete from public.admin_permission_grants where admin_user_id=v_target;
    insert into public.admin_permission_grants(admin_user_id,permission_key,is_allowed,granted_by)
      select v_target, unnest(v_permissions), true, v_actor;
    v_code := v_staff.admin_code;
    v_details := jsonb_build_object('email',lower(trim(p_email)),'admin_code',v_code,
      'department_key',p_department_key,'permissions',to_jsonb(v_permissions),'reactivated',true);
  else
    if not found or v_staff.admin_level <> 'assistant_admin' then raise exception 'এই ব্যবহারকারী Assistant Admin নন।'; end if;
    update public.admin_staff set is_active=false,updated_at=now() where user_id=v_target;
    v_code := v_staff.admin_code;
    v_details := jsonb_build_object('email',lower(trim(p_email)),'admin_code',v_code,'is_active',false);
  end if;

  insert into public.admin_audit_logs(actor_user_id,actor_admin_code,action_key,target_type,target_id,reason,details)
  values(v_actor,v_actor_code,'assistant_admin.'||p_action,'admin_staff',v_target::text,
    'Super Admin dashboard action',v_details);
  return jsonb_build_object('success',true,'admin_code',v_code,'action',p_action);
end;
$function$

CREATE OR REPLACE FUNCTION private.review_profile_change_request(p_request_id uuid, p_approve boolean, p_admin_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_request public.profile_change_requests%rowtype;
begin
  if not private.is_nexora_super_admin() then raise exception 'Only Super Admin can review profile requests' using errcode='42501'; end if;
  if p_approve is null then raise exception 'Approval decision is required'; end if;
  select * into v_request from public.profile_change_requests where id=p_request_id for update;
  if not found then raise exception 'Profile change request not found'; end if;
  if v_request.status <> 'pending' then raise exception 'This request has already been reviewed'; end if;
  if v_request.requested_full_name is null or length(trim(v_request.requested_full_name)) not between 1 and 150 then
    raise exception 'Invalid requested name';
  end if;
  if p_approve then
    update public.profiles set full_name=trim(v_request.requested_full_name),updated_at=now() where id=v_request.user_id;
    if not found then raise exception 'Profile not found'; end if;
    update public.profile_change_requests set status='approved',admin_note=nullif(trim(p_admin_note),''),reviewed_by=auth.uid(),reviewed_at=now() where id=p_request_id;
  else
    update public.profile_change_requests set status='rejected',admin_note=nullif(trim(p_admin_note),''),reviewed_by=auth.uid(),reviewed_at=now() where id=p_request_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION private.review_role_request(request_id uuid, decision text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_request public.role_requests%rowtype;
begin
  if not private.is_nexora_super_admin() then raise exception 'Only Super Admin can review requests' using errcode='42501'; end if;
  if decision not in ('approved','rejected') then raise exception 'Invalid decision'; end if;
  select * into target_request from public.role_requests where id=request_id and status='pending' for update;
  if not found then raise exception 'Pending request not found'; end if;
  update public.role_requests set status=decision where id=request_id;
  if decision='approved' then
    update public.profiles set role=target_request.requested_role,account_status='active',updated_at=now()
    where id=target_request.user_id;
  end if;
end;
$function$

