CREATE OR REPLACE FUNCTION public.sync_public_business()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then
   delete from public.public_businesses where business_id=old.id;
   return old;
 end if;
 if new.approval_status <> 'approved' then
   delete from public.public_businesses where business_id=new.id;
   return new;
 end if;
 insert into public.public_businesses(business_id,seller_id,display_name,country,city,updated_at)
 values(new.id,new.seller_id,new.display_name,new.country,new.city,now())
 on conflict(business_id) do update set seller_id=excluded.seller_id,display_name=excluded.display_name,
 country=excluded.country,city=excluded.city,updated_at=excluded.updated_at;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_public_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' then
    delete from public.public_identities where id = old.id;
    return old;
  end if;

  insert into public.public_identities (id, full_name, updated_at)
  values (new.id, new.full_name, now())
  on conflict (id) do update
    set full_name = excluded.full_name,
        updated_at = excluded.updated_at;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_profile_updates()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
    -- Trusted service-role backend
    IF auth.role() = 'service_role' THEN
        RETURN NEW;
    END IF;

    -- Admin can update profiles
    IF public.is_nexora_admin() THEN
        RETURN NEW;
    END IF;

    -- Users can only update their own profile
    IF auth.uid() IS NULL OR auth.uid() <> OLD.id THEN
        RAISE EXCEPTION 'You cannot modify another user profile';
    END IF;

    -- Seller and Porter require Admin approval
    IF OLD.role IS DISTINCT FROM 'buyer' THEN
        RAISE EXCEPTION 'Profile changes require admin approval';
    END IF;

    -- Buyer can change only full_name
    IF (to_jsonb(NEW) - 'full_name' - 'updated_at')
       IS DISTINCT FROM
       (to_jsonb(OLD) - 'full_name' - 'updated_at') THEN
        RAISE EXCEPTION 'You cannot modify protected profile fields';
    END IF;

    IF NEW.full_name IS NULL
       OR length(trim(NEW.full_name)) NOT BETWEEN 1 AND 150 THEN
        RAISE EXCEPTION 'Invalid full name';
    END IF;

    NEW.updated_at := now();

    RETURN NEW;
END;
$function$
